package ro.leo.visual;
import android.content.*;import android.util.Base64;import com.jcraft.jsch.*;import org.json.*;import java.io.*;import java.security.*;import java.util.*;
/** SSH transport with explicit pinned host-key trust. No saved passwords or auto-login. */
final class PocketSsh implements Closeable {
 final Context context;Session session;ChannelShell shell;ChannelSftp sftp;Repo repo;private OutputStream input;private Thread reader;
 interface Output{void text(String value);}
 PocketSsh(Context c){context=c;}
 static String fingerprint(byte[] key)throws Exception{return "SHA256:"+Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(key),Base64.NO_WRAP|Base64.NO_PADDING);}
 final class Repo implements HostKeyRepository {
  JSONArray trusted;HostKey candidate;boolean changed;
  Repo()throws Exception{JSONObject data=PocketStore.read(context,"ssh-hosts");trusted=data.optJSONArray("keys")==null?new JSONArray():data.getJSONArray("keys");}
  public int check(String host,byte[] key){try{for(int n=0;n<trusted.length();n++){JSONObject row=trusted.getJSONObject(n);if(row.getString("host").equals(host)){if(MessageDigest.isEqual(Base64.decode(row.getString("key"),Base64.DEFAULT),key))return OK;changed=true;return CHANGED;}}candidate=new HostKey(host,key);return NOT_INCLUDED;}catch(Exception e){changed=true;return CHANGED;}}
  public void add(HostKey h,UserInfo info){}public void remove(String h,String t){}public void remove(String h,String t,byte[] k){}public String getKnownHostsRepositoryID(){return "Leo pinned hosts";}public HostKey[] getHostKey(){return new HostKey[0];}public HostKey[] getHostKey(String h,String t){return new HostKey[0];}
  void trust()throws Exception{if(candidate==null||changed)throw new IOException("Changed/unknown host key cannot be approved");if(trusted.length()>=100)throw new IOException("Maximum 100 pinned hosts");trusted.put(new JSONObject().put("host",candidate.getHost()).put("key",candidate.getKey()).put("type",candidate.getType()));PocketStore.write(context,"ssh-hosts",new JSONObject().put("keys",trusted));}
 }
 void connect(String host,int port,String user,char[] password)throws Exception{close();if(host.isEmpty()||host.length()>253||host.matches(".*[\\s\\p{Cntrl}].*")||port<1||port>65535||user.trim().isEmpty()||user.length()>100)throw new IOException("Invalid SSH host/user/port");repo=new Repo();JSch jsch=new JSch();jsch.setHostKeyRepository(repo);Session candidate=jsch.getSession(user,host,port);candidate.setHostKeyAlias(host+":"+port);candidate.setConfig("StrictHostKeyChecking","yes");candidate.setConfig("PreferredAuthentications","password,keyboard-interactive");candidate.setConfig("server_host_key","ecdsa-sha2-nistp256,ecdsa-sha2-nistp384,ecdsa-sha2-nistp521,rsa-sha2-512,rsa-sha2-256");candidate.setConfig("kex","ecdh-sha2-nistp256,ecdh-sha2-nistp384,ecdh-sha2-nistp521,diffie-hellman-group14-sha256");candidate.setPassword(new String(password));candidate.setServerAliveInterval(15000);candidate.setServerAliveCountMax(3);try{candidate.connect(10000);session=candidate;}catch(Exception e){candidate.disconnect();throw e;}}
 boolean connected(){return session!=null&&session.isConnected();}
 void startShell(final Output output)throws Exception{if(!connected())throw new IOException("Disconnected");if(shell!=null&&shell.isConnected())return;shell=(ChannelShell)session.openChannel("shell");shell.setPtyType("vt100",30,14,240,224);final InputStream stream=shell.getInputStream();input=shell.getOutputStream();shell.connect(8000);reader=new Thread(new Runnable(){public void run(){try{byte[] bytes=new byte[2048];java.io.Reader text=new InputStreamReader(stream,"UTF-8");char[] chars=new char[2048];int n;while((n=text.read(chars))!=-1)output.text(new String(chars,0,n));}catch(Exception e){output.text("\n[SSH disconnected]\n");}}},"LeoSshOutput");reader.setDaemon(true);reader.start();}
 synchronized void send(String value)throws IOException{if(input==null||shell==null||!shell.isConnected())throw new IOException("Shell disconnected");input.write(value.getBytes("UTF-8"));input.flush();}
 ChannelSftp files()throws Exception{if(!connected())throw new IOException("Disconnected");if(sftp==null||!sftp.isConnected()){sftp=(ChannelSftp)session.openChannel("sftp");sftp.connect(8000);}return sftp;}
 File get(String remote,File destination)throws Exception{ChannelSftp c=files();long expected=c.lstat(remote).getSize();if(expected<0||expected>100L*1024*1024||destination.exists())throw new IOException("SFTP limit: 100 MiB; output must be new");File temp=File.createTempFile(".leo-sftp-",".part",destination.getParentFile());try{long done=0;try(InputStream in=c.get(remote);FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();done+=n;if(done>100L*1024*1024)throw new IOException("SFTP size limit");out.write(b,0,n);}out.getFD().sync();}if(done!=expected||c.lstat(remote).getSize()!=expected)throw new IOException("Remote size changed");java.nio.file.Files.move(temp.toPath(),destination.toPath());return destination;}finally{temp.delete();}}
 void put(File local,String remote)throws Exception{if(!local.isFile()||local.length()>100L*1024*1024)throw new IOException("SFTP limit: 100 MiB");ChannelSftp c=files();try{c.lstat(remote);throw new IOException("Remote filename already exists");}catch(SftpException e){if(e.id!=ChannelSftp.SSH_FX_NO_SUCH_FILE)throw e;}try(InputStream in=new FileInputStream(local)){c.put(in,remote);}if(c.lstat(remote).getSize()!=local.length())throw new IOException("Upload size mismatch");}
 public void close(){if(sftp!=null)sftp.disconnect();sftp=null;if(shell!=null)shell.disconnect();shell=null;if(session!=null)session.disconnect();session=null;input=null;if(reader!=null)reader.interrupt();reader=null;}
}
